function setupCalendar(){calendarMonth=dateISO().slice(0,7);const more=$('#more'),main=$('main');if(!more||!main||$('#calendar'))return;const opener=document.createElement('button');opener.type='button';opener.className='secondary-btn';opener.textContent='Finans takvimini aç';opener.onclick=()=>{document.querySelectorAll('.page').forEach(page=>page.classList.toggle('active',page.id==='calendar'));document.querySelectorAll('nav button').forEach(button=>button.classList.remove('selected'));$('#pageTitle').textContent='Finans Takvimi';renderCalendar()};more.insertBefore(opener,$('#backupBtn'));const page=document.createElement('section');page.id='calendar';page.className='page';page.innerHTML='<div class="ledger-head"><h2>Finans takvimi</h2><button type="button" class="green-link" data-calendar-back>Ana sayfa</button></div><article class="glass-card"><div class="ledger-head"><button type="button" class="textButton" data-calendar-shift="-1">‹ Önceki</button><b id="calendarTitle"></b><button type="button" class="textButton" data-calendar-shift="1">Sonraki ›</button></div><p class="formHint">Planlanan kayıtlar bakiyeyi değiştirmez. İşlenmiş hareketler ayrı gösterilir.</p><div id="calendarList" class="budget-list"></div></article>';main.append(page);page.querySelector('[data-calendar-back]').onclick=()=>{document.querySelectorAll('.page').forEach(item=>item.classList.toggle('active',item.id==='more'));$('#pageTitle').textContent='Ayarlar'};page.querySelectorAll('[data-calendar-shift]').forEach(button=>button.onclick=()=>{calendarMonth=FinanceCore.addMonths(`${calendarMonth}-01`,Number(button.dataset.calendarShift)).slice(0,7);renderCalendar()})}
