async function exportStructuredData(){const snapshot={format:'cep-finans-data-export',version:1,exportedAt:new Date().toISOString(),stores:{}};for(const storeName of BACKUP_STORES)snapshot.stores[storeName]=storeName==='accounts'?state.accounts:storeName==='transactions'?state.transactions:await all(storeName);if(!Object.values(snapshot.stores).some(records=>records.length)){toast('Dışa aktarılacak kayıt yok.');return}download(JSON.stringify(snapshot,null,2),`cep-finans-veri-disa-aktarim-${dateISO()}.json`);toast('Yapılandırılmış veri dosyası indirildi')}
