function renderUpcoming(){const box=$('#upcomingList');if(!box)return;const start=dateISO(),end=FinanceCore.addMonths(start,0),events=[];for(let day=0;day<8;day++){const date=new Date(`${start}T12:00`);date.setDate(date.getDate()+day);const iso=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;for(const recurring of state.recurring.filter(item=>item.active!==false&&item.nextDueDate===iso))events.push({date:iso,title:recurring.name,detail:`Düzenli ${recurring.direction==='income'?'gelir':'ödeme'} • ${money(recurring.amountMinor/100)}`});for(const debt of [...state.debts,...state.loans].filter(item=>item.active!==false&&item.nextDueDate===iso))events.push({date:iso,title:debt.name,detail:`${debt.direction==='incoming'?'Tahsilat':'Ödeme'} • ${money(debt.monthlyPaymentMinor/100)}`});for(const card of state.accounts.filter(item=>item.type==='card'&&item.closingDay)){const cycle=FinanceCore.cardCycleWithDueOffset(iso,card.closingDay,10,Boolean(card.closingDayPurchasesNext));if(cycle.dueDate===iso)events.push({date:iso,title:card.name,detail:'Kart son ödeme tarihi'})}}box.innerHTML=events.length?events.sort((a,b)=>a.date.localeCompare(b.date)).map(event=>`<div class="budget-row"><b><span>${esc(event.title)}</span><span>${fmtDate(event.date)}</span></b><small>${esc(event.detail)}</small></div>`).join(''):'<div class="budget-row"><b>Yaklaşan ödeme yok</b><small>Önümüzdeki 7 gün için yerel kayıtlarınızda vade bulunmuyor.</small></div>'}
function setupUpcoming(){const dashboard=$('#dashboard');if(!dashboard||$('#upcomingList'))return;const section=document.createElement('section');section.className='ledger';section.innerHTML='<div class="ledger-head"><h2>Yaklaşanlar</h2></div><div id="upcomingList" class="budget-list"></div>';dashboard.append(section);new MutationObserver(renderUpcoming).observe($('#transactionsList'),{childList:true,subtree:true});renderUpcoming()}
