function goalContributionForm(goalId){const goal=state.goals.find(g=>g.id===goalId);if(!goal)return;show(`<h2 class="formTitle">Hedefe katkı ekle</h2><p class="formHint">Bu, birikim hedefi tahsisini günceller; banka bakiyesinde ayrıca değişiklik yapmaz. Para hareketini ayrıca kaydedin.</p><p class="formHint">${esc(goal.name)}: ${money(goal.currentMinor/100)} / ${money(goal.targetMinor/100)}</p><label class="field">Katkı tutarı (TL)<input required name="amount" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Tarih<input required name="date" type="date" value="${dateISO()}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async f=>{try{const amountMinor=FinanceCore.minor(f.get('amount'));if(amountMinor<=0)throw new Error('Katkı tutarı sıfırdan büyük olmalı.');const currentMinor=goal.currentMinor+amountMinor;await put('savingsGoals',{...goal,currentMinor,status:currentMinor>=goal.targetMinor?'completed':'active',updatedAt:dateISO()});await put('goalContributions',{id:id(),schemaVersion:1,goalId,amountMinor,date:FinanceCore.date(f.get('date')),createdAt:dateISO()});await load();toast('Hedef katkısı kaydedildi')}catch(error){toast(error.message||'Katkı kaydedilemedi.')}})}
